from PIL import Image
import numpy as np

for f in ["obs_0006", "obs_0011", "obs_0012", "obs_0013"]:
    arr = np.array(Image.open(f"/work/observations/{f}.png"))
    m = (arr[:, :, 0] > 100) & (arr[:, :, 0] < 160) & (arr[:, :, 1] > 40) & (arr[:, :, 1] < 80) & (arr[:, :, 2] < 30)
    y, x = np.where(m)
    if len(x) > 50:
        print(f"{f}: chair count={len(x)}, x=[{x.min()}, {x.max()}], y=[{y.min()}, {y.max()}]")
'", "description": "Check if chair appeared in earlier frames"}

