import numpy as np
from PIL import Image

arr = np.array(Image.open('/work/observations/obs_0001.png').convert('RGB'))

# Let's see unique RGBs with counts > 100
colors, counts = np.unique(arr.reshape(-1, 3), axis=0, return_counts=True)
for c, cnt in sorted(zip(colors, counts), key=lambda x: -x[1])[:30]:
    if cnt > 100:
        print(f'{c.tolist()}: {cnt}')
"", "description": "Find dominant colors in obs 1"}

